function apply(pref){current=pref==="auto"?device():(CODES.includes(pref)?pref:"en");document.documentElement.lang=current;document.documentElement.dir=current==="ar"?"rtl":"ltr";document.documentElement.classList.toggle("ac-rtl",current==="ar");scan(document.body);try{if(window.AndroidBridge&&typeof window.AndroidBridge.setLanguagePack==="function")window.AndroidBridge.setLanguagePack(current,JSON.stringify({language:current,translations:D[current]||{},english:D.en||{}}))}catch(e){}const s=document.getElementById("ac-language-select");if(s)s.value=pref;window.dispatchEvent(new CustomEvent("allconvert:languagechange",{detail:{language:current,preference:pref}}))}
function picker(){if(document.getElementById("ac-language-control"))return;const box=document.createElement("label");box.id="ac-language-control";box.innerHTML='<span aria-hidden="true">◎</span><select id="ac-language-select" aria-label="Language"></select>';const s=box.querySelector("select");const opt=document.createElement("option");opt.value="auto";opt.textContent="Auto · Device";s.appendChild(opt);CODES.forEach(c=>{const o=document.createElement("option");o.value=c;o.textContent=NAMES[c];s.appendChild(o)});s.value=preference;s.addEventListener("change",()=>{preference=s.value;try{localStorage.setItem(KEY,preference)}catch(e){}apply(preference)});const host=document.querySelector("header,.app-header,.topbar,.navbar,.brand-header,.header");if(host)host.appendChild(box);else{box.classList.add("ac-language-floating");document.body.appendChild(box)}}
